function exemplo() {
  if (true) {
    var a = 1;
    let b = 2;
  }
  console.log(a); // 1 — var "escapa" do bloco
  console.log(b); // ReferenceError — b só existe dentro do if
}

console.log(x); // undefined (var foi içada, sem valor ainda)
var x = 10;

console.log(y); // ReferenceError: Cannot access 'y' before initialization
let y = 20;

function criarContador() {
  let contagem = 0;
  return function () {
    contagem += 1;
    return contagem;
  };
}

const contador = criarContador();
console.log(contador()); // 1
console.log(contador()); // 2
console.log(contador()); // 3 — "contagem" continua viva entre chamadas

