function criarContaBancaria(saldoInicial) {
  let saldo = saldoInicial;
  return {
    depositar(valor) { saldo += valor; return saldo; },
    consultarSaldo() { return saldo; },
  };
}

function memoizar(fn) {
  const cache = new Map();
  return function (argumento) {
    if (cache.has(argumento)) {
      return cache.get(argumento);
    }
    const resultado = fn(argumento);
    cache.set(argumento, resultado);
    return resultado;
  };
}

const fibonacci = memoizar(function fib(n) {
  return n < 2 ? n : fibonacci(n - 1) + fibonacci(n - 2);
});

console.log(fibonacci(40)); // 102334155, calculado quase instantaneamente
